import{_ as n,C as i,o as s,c as l,a0 as o,j as e,a as r,E as c}from"./chunks/framework.C5ukcOJf.js";const b=JSON.parse('{"title":"OAuth2","description":"","frontmatter":{},"headers":[],"relativePath":"docs/concepts/oauth2.md","filePath":"docs/concepts/oauth2.md"}'),d={name:"docs/concepts/oauth2.md"};function h(u,t,f,g,p,m){const a=i("Badge");return s(),l("div",null,[t[5]||(t[5]=o('<h1 id="oauth2" tabindex="-1">OAuth2 <a class="header-anchor" href="#oauth2" aria-label="Permalink to &quot;OAuth2&quot;">​</a></h1><p>OAuth2 is vast, detailed and complex. There will way to distill OAuth2 in a simple <code>README</code>. Instead, here is a glossary of common terms used in the context of OAuth2.</p><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><h3 id="oauth-2-0" tabindex="-1">OAuth 2.0 <a class="header-anchor" href="#oauth-2-0" aria-label="Permalink to &quot;OAuth 2.0&quot;">​</a></h3><ul><li><a href="https://datatracker.ietf.org/doc/html/rfc6749" target="_blank" rel="noreferrer">RFC 6749: The OAuth 2.0 Authorization Framework</a></li><li><a href="https://datatracker.ietf.org/doc/html/rfc6750" target="_blank" rel="noreferrer">RFC 6750: The OAuth 2.0 Authorization Framework: Bearer Token Usage</a></li><li><a href="https://datatracker.ietf.org/doc/html/rfc8414" target="_blank" rel="noreferrer">RFC 8414: OAuth 2.0 Authorization Server Metadata</a></li><li><a href="https://datatracker.ietf.org/doc/html/rfc8252" target="_blank" rel="noreferrer">RFC 8252: OAuth 2.0 for Native Apps</a></li><li><a href="https://datatracker.ietf.org/doc/html/rfc9207" target="_blank" rel="noreferrer">RFC 9207: OAuth 2.0 Authorization Server Issuer Identification</a></li><li><a href="https://datatracker.ietf.org/doc/html/rfc7636" target="_blank" rel="noreferrer">RFC 7636: Proof Key for Code Exchange by OAuth Public Clients (PKCE)</a></li><li><a href="https://datatracker.ietf.org/doc/html/rfc7009" target="_blank" rel="noreferrer">RFC 7009: OAuth 2.0 Token Revocation</a></li><li><a href="https://datatracker.ietf.org/doc/html/rfc7662" target="_blank" rel="noreferrer">RFC 7662: OAuth 2.0 Token Introspection</a></li><li><a href="https://datatracker.ietf.org/doc/html/rfc9449" target="_blank" rel="noreferrer">RFC 9449: OAuth 2.0 Demonstrating Proof of Possession (DPoP)</a></li></ul><h4 id="guidance" tabindex="-1">Guidance <a class="header-anchor" href="#guidance" aria-label="Permalink to &quot;Guidance&quot;">​</a></h4><ul><li><a href="https://datatracker.ietf.org/doc/html/rfc9700" target="_blank" rel="noreferrer">RFC 9700: Best Current Practice for OAuth 2.0 Security</a></li><li><a href="https://datatracker.ietf.org/doc/html/rfc6819" target="_blank" rel="noreferrer">RFC 6819: OAuth 2.0 Threat Model and Security Considerations</a></li></ul><h3 id="json-web-specs" tabindex="-1">JSON Web Specs <a class="header-anchor" href="#json-web-specs" aria-label="Permalink to &quot;JSON Web Specs&quot;">​</a></h3><ul><li><a href="https://datatracker.ietf.org/doc/html/rfc7519" target="_blank" rel="noreferrer">RFC 7519: JSON Web Token (JWT)</a></li><li><a href="https://datatracker.ietf.org/doc/html/rfc7515" target="_blank" rel="noreferrer">RFC 7515: JSON Web Signature (JWS)</a></li><li><a href="https://datatracker.ietf.org/doc/html/rfc7517" target="_blank" rel="noreferrer">RFC 7517: JSON Web Key (JWK)</a></li></ul><h3 id="oidc" tabindex="-1">OIDC <a class="header-anchor" href="#oidc" aria-label="Permalink to &quot;OIDC&quot;">​</a></h3><ul><li><a href="https://openid.net/specs/openid-connect-core-1_0.html" target="_blank" rel="noreferrer">OpenID Connect (OIDC) Spec</a></li><li><a href="https://openid.net/specs/openid-connect-discovery-1_0.html" target="_blank" rel="noreferrer">OpenID Connect (OIDC) Discovery Spec</a></li></ul><h3 id="http" tabindex="-1">HTTP <a class="header-anchor" href="#http" aria-label="Permalink to &quot;HTTP&quot;">​</a></h3><ul><li><a href="https://datatracker.ietf.org/doc/html/rfc7235" target="_blank" rel="noreferrer">RFC 7235: Hypertext Transfer Protocol (HTTP/1.1): Authentication</a></li></ul><h2 id="common-terms" tabindex="-1">Common Terms <a class="header-anchor" href="#common-terms" aria-label="Permalink to &quot;Common Terms&quot;">​</a></h2><ul><li><strong><code>Issuer:</code></strong> The authorization server (or identity provider) that authenticates users and issues ID tokens.</li><li><strong><code>Scope:</code></strong> Specifies the level of access requested by the client, such as read or write permissions for resources.</li><li><strong><code>JWT (JSON Web Token):</code></strong> A compact, URL-safe token format often used for access tokens, containing claims about the user and token validity.</li><li><strong><code>Token Expiry:</code></strong> The duration after which an access token becomes invalid and must be refreshed or reissued.</li><li><strong><code>Token Revocation:</code></strong> The process of invalidating a token before its expiry, preventing further access to resources.</li><li><strong><code>Consent Screen:</code></strong> The user interface (UI) presented to the resource owner to approve or deny access requested by the client.</li><li><strong><code>Claims:</code></strong> Statements about an entity (usually the user) and additional metadata, typically included in tokens.</li><li><strong><code>State:</code></strong> The state parameter is a unique value sent by the client during authentication to prevent cross-site request forgery (CSRF) attacks. When the authorization server returns this value, the client verifies it matches the original, ensuring the response belongs to its own request and maintaining security.</li><li><strong><code>Nonce:</code></strong> A random value included in authentication requests to prevent replay attacks.</li><li><strong><code>PKCE (Proof Key for Code Exchange):</code></strong> An extension to OAuth2 used to secure public clients in the Authorization Code Grant flow.</li><li><strong><code>DPoP (Demonstration of Proof-of-Possession):</code></strong> An extension to OAuth2 and OIDC designed to prevent token replay attacks by binding tokens to a particular client and request.</li></ul><h2 id="actors" tabindex="-1">Actors <a class="header-anchor" href="#actors" aria-label="Permalink to &quot;Actors&quot;">​</a></h2><ul><li><strong><code>Authorization Server:</code></strong> The server that issues access tokens after authenticating and authorizing the client and resource owner.</li><li><strong><code>Resource Server:</code></strong> The server that hosts protected resources and validates access tokens to grant access.</li><li><strong><code>Client:</code></strong> The application requesting access to protected resources on behalf of the resource owner.</li><li><strong><code>Resource Owner:</code></strong> The user or entity who owns the protected resources and grants access to the client.</li><li><strong><code>Relying Party (RP):</code></strong> The application (client) that requests authentication and user information from the identity provider.</li><li><strong><code>Identity Provider (IdP):</code></strong> The service that authenticates users and provides identity information (often the same as the issuer).</li></ul><h2 id="tokens" tabindex="-1">Tokens <a class="header-anchor" href="#tokens" aria-label="Permalink to &quot;Tokens&quot;">​</a></h2><ul><li><strong><code>Access Token:</code></strong> A credential used by the client to access protected resources; typically short-lived.</li><li><strong><code>ID Token:</code></strong> A JWT token issued by the identity provider containing claims about the authenticated user.</li><li><strong><code>Refresh Token:</code></strong> A credential used to obtain a new access token without re-authenticating the resource owner; typically long-lived.</li></ul><h2 id="flows-grant-types" tabindex="-1">Flows / Grant Types <a class="header-anchor" href="#flows-grant-types" aria-label="Permalink to &quot;Flows / Grant Types&quot;">​</a></h2><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>Despite the section title, these two words aren&#39;t quite synonyms. A <strong>grant type</strong> is a formally spec&#39;d mechanism identified by the <code>grant_type</code> parameter sent to the token endpoint (e.g. <code>authorization_code</code>, <code>refresh_token</code>) — it describes the specific thing being redeemed for a token. A <strong>flow</strong> is the broader, end-to-end journey a client and user go through to get there in the first place, including steps that never touch the token endpoint at all (redirects, consent screens, PKCE, device-code polling, etc.).</p></div>',21)),e("ul",null,[t[2]||(t[2]=e("li",null,[e("strong",null,[e("code",null,"Authorization Grant:")]),r(" The credential representing the resource owner's authorization; used by the client to obtain an access token. "),e("ul",null,[e("li",null,[e("strong",null,[e("code",null,"Authorization Code:")]),r(" A temporary code exchanged for an access token (used in Authorization Code Grant flow).")]),e("li",null,[e("strong",null,[e("code",null,"Redirect URI:")]),r(" The URI where the authorization server redirects the user after authorization, often used to deliver authorization codes or tokens.")])])],-1)),e("li",null,[t[0]||(t[0]=e("strong",null,[e("code",null,"Implicit Grant:")],-1)),c(a,{type:"danger",text:"Deprecated"}),t[1]||(t[1]=r(" An OAuth2 flow where the access token is returned directly to the client, suitable for public clients like single-page apps.",-1))]),t[3]||(t[3]=e("li",null,[e("strong",null,[e("code",null,"Client Credentials Grant:")]),r(" An OAuth2 flow where the client authenticates using its own credentials, typically for machine-to-machine communication.")],-1)),t[4]||(t[4]=e("li",null,[e("strong",null,[e("code",null,"Password Grant:")]),r(" An OAuth2 flow where the client obtains an access token by directly using the resource owner's username and password.")],-1))]),t[6]||(t[6]=o('<h2 id="oauth2-extensions" tabindex="-1">OAuth2 Extensions <a class="header-anchor" href="#oauth2-extensions" aria-label="Permalink to &quot;OAuth2 Extensions&quot;">​</a></h2><ul><li><strong><code>OpenID Connect (OIDC):</code></strong> An identity layer built on top of OAuth2, used to verify a user&#39;s identity and obtain basic profile information. <ul><li><strong><code>Single Sign-On (SSO):</code></strong> The ability for users to authenticate once and access multiple applications without re-authenticating.</li><li><strong><code>Single Logout (SLO):</code></strong> A mechanism to log the user out of all connected applications and sessions.</li><li><strong><code>UserInfo Endpoint:</code></strong> An API endpoint provided by the IdP that returns additional user profile information.</li></ul></li></ul>',2))])}const y=n(d,[["render",h]]);export{b as __pageData,y as default};
